INSERT INTO destination (slug, name, flag, region, vibes, tagline, description, best_time_to_visit, hero_image_url, lat, lng, sort_order) VALUES ('italy', 'Italy', '🇮🇹', 'Europe', 'Nature,Beach,Culture', 'Jagged peaks in the north, turquoise coves in the south.', 'La dolce vita, starting with the Dolomites and Sardinia - more regions coming soon.', 'June - September (Dolomites hiking, Sardinia beaches)', 'https://images.unsplash.com/photo-1531219432768-9f540ce91ef3?auto=format&fit=crop&w=1600&q=75', 41.87, 12.57, 9);
