INSERT INTO destination (slug, name, flag, region, vibes, tagline, description, best_time_to_visit, hero_image_url, lat, lng, sort_order) VALUES ('norway', 'Norway', '🇳🇴', 'Europe', 'Nature', 'Fjords, fishing villages and the Northern Lights.', 'Dramatic fjords, red cabins on the water and Arctic adventures above the polar circle. Norway is the place where you take a train through the mountains in the morning, kayak a fjord in the afternoon and wait for the sky to turn green at night.', 'June - August (fjords, hiking, midnight sun) and late September - March (Northern Lights)', 'https://images.unsplash.com/photo-1513519245088-0e12902e5a38?auto=format&fit=crop&w=1600&q=75', 60.47, 8.47, 10);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'norway'), 'oslo', 'Oslo', 'A green, relaxed capital on the water, with world-class museums and saunas right on the fjord.', 'The Nobel Peace Prize is the only Nobel Prize awarded outside Sweden - it is presented every 10 December in Oslo City Hall.', 'https://images.unsplash.com/photo-1601439678777-b2b3c56fa627?auto=format&fit=crop&w=1600&q=75', 0);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'oslo'), 1, 'Walk on the Opera House roof', 'The sloping white marble roof rises straight out of the fjord - walk all the way to the top for sunset.', 'https://images.unsplash.com/photo-1601439678777-b2b3c56fa627?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'oslo'), 2, 'Vigeland Sculpture Park', 'More than 200 sculptures by Gustav Vigeland in Frogner Park, free and open all day.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'oslo'), 3, 'MUNCH museum', 'Edvard Munch''s work, including versions of The Scream, in a striking building on the harbour.', 'https://images.unsplash.com/photo-1601439678777-b2b3c56fa627?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'oslo'), 4, 'Bygdoy museums by ferry', 'Polar ships at the Fram Museum and Thor Heyerdahl''s raft at the Kon-Tiki Museum.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'oslo'), 5, 'Floating fjord sauna', 'Heat up in a sauna on the water, then jump into the fjord - the Norwegian way, all year round.', 'https://images.unsplash.com/photo-1513519245088-0e12902e5a38?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'oslo'), 'https://images.unsplash.com/photo-1601439678777-b2b3c56fa627?auto=format&fit=crop&w=1200&q=75', 'Oslo harbour', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'oslo'), 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=1200&q=75', 'Oslofjord', 1);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'norway'), 'bergen-the-fjords', 'Bergen & the Fjords', 'The colourful Hanseatic port city and the gateway to Norway''s most famous fjords.', 'Bergen is one of the rainiest cities in Europe, with rain on more than 200 days a year - locals joke that babies here are born with umbrellas.', 'https://images.unsplash.com/photo-1513519245088-0e12902e5a38?auto=format&fit=crop&w=1600&q=75', 1);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'bergen-the-fjords'), 1, 'Bryggen wharf', 'Wander the narrow alleys behind the colourful wooden merchant houses, a UNESCO World Heritage site.', 'https://images.unsplash.com/photo-1601439678777-b2b3c56fa627?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'bergen-the-fjords'), 2, 'Floibanen funicular to Mount Floyen', 'Ride up in minutes for the classic view over the city, then hike back down through the forest.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'bergen-the-fjords'), 3, 'Flam Railway and Naeroyfjord cruise', 'One of the steepest standard-gauge railways in the world, then a boat through one of its narrowest fjords.', 'https://images.unsplash.com/photo-1513519245088-0e12902e5a38?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'bergen-the-fjords'), 4, 'Hike Trolltunga (summer)', 'A long, tough day hike to the famous rock ledge hanging 700 m above Lake Ringedalsvatnet.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'bergen-the-fjords'), 5, 'Fish Market lunch', 'Fresh shrimp, king crab and fish soup right on the harbour.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'bergen-the-fjords'), 'https://images.unsplash.com/photo-1513519245088-0e12902e5a38?auto=format&fit=crop&w=1200&q=75', 'Fjord view', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'bergen-the-fjords'), 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=1200&q=75', 'Mountains above the fjord', 1);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'norway'), 'lofoten', 'Lofoten', 'Jagged peaks rising straight out of the sea, red fishing cabins and white-sand Arctic beaches.', 'Lofoten is above the Arctic Circle, yet thanks to the Gulf Stream its winters are much milder than other places that far north.', 'https://images.unsplash.com/photo-1513519245088-0e12902e5a38?auto=format&fit=crop&w=1600&q=75', 2);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'lofoten'), 1, 'Reine and Hamnoy at golden hour', 'The postcard view of red cabins, still water and sharp peaks - best from the bridges.', 'https://images.unsplash.com/photo-1513519245088-0e12902e5a38?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'lofoten'), 2, 'Hike Reinebringen', 'About 2,000 stone steps up for one of the most famous viewpoints in Norway.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'lofoten'), 3, 'Sleep in a rorbu', 'A traditional fisherman''s cabin on stilts over the water.', 'https://images.unsplash.com/photo-1601439678777-b2b3c56fa627?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'lofoten'), 4, 'Arctic surfing at Unstad', 'Surf under the midnight sun or the Northern Lights, with a thick wetsuit.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'lofoten'), 5, 'Lofotr Viking Museum', 'A reconstruction of the largest Viking longhouse ever found, with a Viking feast in summer.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'lofoten'), 'https://images.unsplash.com/photo-1513519245088-0e12902e5a38?auto=format&fit=crop&w=1200&q=75', 'Lofoten fishing village', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'lofoten'), 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=1200&q=75', 'Arctic peaks', 1);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'norway'), 'tromso', 'Tromso', 'The capital of the Arctic and one of the best bases in the world for seeing the Northern Lights.', 'In Tromso the sun does not rise at all from late November to mid-January (polar night), and it does not set from late May to late July (midnight sun).', 'https://images.unsplash.com/photo-1531366936337-7c912a4589a7?auto=format&fit=crop&w=1600&q=75', 3);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'tromso'), 1, 'Northern Lights chase', 'Small-group tours drive away from the clouds and city lights to find the aurora.', 'https://images.unsplash.com/photo-1531366936337-7c912a4589a7?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'tromso'), 2, 'Husky sledding', 'Drive your own team of dogs across snowy valleys.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'tromso'), 3, 'Fjellheisen cable car', 'Up to Storsteinen, 421 m above the city, for the view at sunset or under the aurora.', 'https://images.unsplash.com/photo-1601439678777-b2b3c56fa627?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'tromso'), 4, 'Whale watching (November - January)', 'Orcas and humpbacks follow the herring into the northern fjords in winter.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'tromso'), 5, 'Reindeer and Sami culture', 'Feed reindeer and listen to joik songs and stories in a lavvu tent by the fire.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'tromso'), 'https://images.unsplash.com/photo-1531366936337-7c912a4589a7?auto=format&fit=crop&w=1200&q=75', 'Northern Lights', 0);
